#!/usr/bin/env node
// Copies @clerk/ui's appearance types into src/vendor, so the published types
// describe `appearance` without apps installing @clerk/ui, which declares
// React peers. @clerk/react inlines the same file into its own types.
//
//   node scripts/vendor-clerk-ui-types.mjs          # write the vendored file
//   node scripts/vendor-clerk-ui-types.mjs --check  # fail if it is stale

import fs from 'node:fs';
import { createRequire } from 'node:module';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const packageDir = path.resolve(
  path.dirname(fileURLToPath(import.meta.url)),
  '..'
);
export const vendoredPath = path.join(
  packageDir,
  'src/vendor/clerk-ui-appearance.d.ts'
);

/** The vendored file for the installed @clerk/ui. */
export const renderVendoredTypes = () => {
  const require = createRequire(path.join(packageDir, 'package.json'));
  const uiDir = path.dirname(require.resolve('@clerk/ui/package.json'));
  const { version } = JSON.parse(
    fs.readFileSync(path.join(uiDir, 'package.json'), 'utf8')
  );
  const source = fs
    .readFileSync(path.join(uiDir, 'dist/internal/appearance.d.ts'), 'utf8')
    .replace(/\n\/\/# sourceMappingURL=.*$/, '\n');
  return (
    `// Generated by scripts/vendor-clerk-ui-types.mjs from @clerk/ui@${version}\n` +
    `// (dist/internal/appearance.d.ts). Do not edit; rerun the script after\n` +
    `// updating @clerk/ui.\n` +
    source
  );
};

if (process.argv[1] === fileURLToPath(import.meta.url)) {
  const expected = renderVendoredTypes();
  if (process.argv.includes('--check')) {
    const current = fs.existsSync(vendoredPath)
      ? fs.readFileSync(vendoredPath, 'utf8')
      : '';
    if (current !== expected) {
      console.error(
        `${path.relative(packageDir, vendoredPath)} is stale. Run node scripts/vendor-clerk-ui-types.mjs.`
      );
      process.exit(1);
    }
  } else {
    fs.writeFileSync(vendoredPath, expected);
    console.log(`Wrote ${path.relative(packageDir, vendoredPath)}`);
  }
}
